import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue accessing URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0]
        rows = table.xpath('.//tr')
        if not rows:
            return 0
        headers = [th.text_content().strip() for th in rows[0].xpath('.//th')]
        data = []
        for row in rows[1:]:
            cols = row.xpath('.//td')
            if not cols:
                continue
            data.append([col.text_content().strip() for col in cols])
        if not data:
            return 0
        if headers:
            df = pd.DataFrame(data, columns=headers)
        else:
            df = pd.DataFrame(data)
        conn = sqlite3.connect(database_name)
        cursor = conn.cursor()
        cursor.execute("DROP TABLE IF EXISTS my_table")
        df.to_sql("my_table", conn, index=False)
        conn.commit()
        row_count = len(df)
        conn.close()
        return row_count
    except IndexError:
        return 0
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    except Exception as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

